import type { SelectOption } from '@linm-soft-org/linm-web-common-components';
import {
  INCIDENT_LIST_STATUS_EXTRA,
  MedicalIncident,
  MedicalIncidentFilters,
} from '../models/MedicalIncident';

export type { IncidentListStatusFilter } from '../models/MedicalIncident';
export { INCIDENT_LIST_STATUS_EXTRA } from '../models/MedicalIncident';

export const INCIDENT_LIST_STATUS_EXTRA_OPTIONS: SelectOption[] = [
  { value: INCIDENT_LIST_STATUS_EXTRA.serviceMismatch, label: 'Nhầm dịch vụ' },
  { value: INCIDENT_LIST_STATUS_EXTRA.notMedicalIncident, label: 'Nhầm sự cố' },
];

export function buildIncidentListStatusOptions(
  incidentStatusOptions: SelectOption[],
): SelectOption[] {
  return [
    { value: '', label: 'Tất cả trạng thái' },
    ...incidentStatusOptions,
    ...INCIDENT_LIST_STATUS_EXTRA_OPTIONS,
  ];
}

/** Map UI status filter (incl. pseudo) → API query fields. */
export function expandIncidentListFilters(
  filters: MedicalIncidentFilters,
): MedicalIncidentFilters {
  const status = filters.status;
  if (status === INCIDENT_LIST_STATUS_EXTRA.serviceMismatch) {
    return {
      ...filters,
      status: undefined,
      isServiceMismatch: true,
      isNotMedicalIncident: undefined,
    };
  }
  if (status === INCIDENT_LIST_STATUS_EXTRA.notMedicalIncident) {
    return {
      ...filters,
      status: undefined,
      isNotMedicalIncident: true,
      isServiceMismatch: undefined,
    };
  }
  return {
    ...filters,
    isServiceMismatch: undefined,
    isNotMedicalIncident: undefined,
  };
}

/** Label for list/export status column — flags override workflow status. */
export function formatIncidentListStatusLabel(
  item: Pick<MedicalIncident, 'status' | 'isServiceMismatch' | 'isNotMedicalIncident'>,
  incidentStatusOptions: SelectOption[],
): string {
  if (item.isNotMedicalIncident) return 'Nhầm sự cố';
  if (item.isServiceMismatch) return 'Nhầm dịch vụ';
  return incidentStatusOptions.find((o) => o.value === item.status)?.label ?? item.status ?? '';
}
